// Jianghu saga (T5): คัมภีร์เก้าอิม — "เก้าเศษเหล็กดำ".
//
// Legend (history, told by elders and flashbacks): ก๊วยเจ๋ง and อึ้งย้ง had
// the black-iron sword of the old days melted into the Dragon Saber and the
// Heaven Sword before เซียงยาง fell, and hid two silks inside: the Nine Yin
// scripture and the war manual. Forty-odd years ago จิวจี้เยียก broke both
// blades on a deserted island, took the Nine Yin silk, tore out the slow
// chapters and kept only the claw (emei_arts tells that night). The war
// manual went to the founding army. What nobody read was the iron itself:
// อึ้งย้ง engraved the scripture's heart — the key that tells the reader
// which way to read — mirror-wise on the blades' inner faces. Broken, the
// two blades made nine shards, and the shards drifted: into the sea, into a
// pirate's drinking hall, into a beggar's gourd, into the court's archive.
//
// The present (1401): the archive's scattering has put the shards loose.
// A blind ferryman on the river — เฒ่าเซวียน, the last disciple of the two
// Xuanming elders, frozen from inside by his own cold palm for forty years —
// has been giving the torn claw chapter away free to anyone in a hurry, and
// hunting the nine shards: he believes the heart will let him take warmth
// from others for ever. The hero follows the shards across the central
// plains, the river and the sea with a talkative young adventurer
// (หลัวเฟย์หาว) who learns the fast claw and falls, a foppish young lord who
// wants his father to look at him, a pirate king who opens wine jars with
// the saber's hilt, both armies of ศึกจิ้งหนาน wanting a war manual that is
// not there, and the old monk of the Duan line who can read the outline.
//
// Theme — the art is its first line: "ทางแห่งฟ้า ตัดส่วนที่ล้น เติมส่วนที่
// พร่อง; ทางของคน ตัดส่วนที่พร่อง ไปเติมส่วนที่ล้น". The same text makes a
// demon of whoever takes from others to fill himself, and a saint of whoever
// gives from his own fullness. The claw stays in the true text: the hand that
// can tear is the hand that knows when to open.
//
// Six acts, 36 chapters: I เศษเหล็กในอวน · II เหล็กดำพูดได้ · III ทะเล ·
// IV ตำราที่ไม่มีอยู่ · V ส่วนที่พร่อง · VI เก้าอิม.
